namespace Engine { internal static class StreamCompat { internal static void ReadExactly(this System.IO.Stream stream, byte[] buffer, int offset, int count) => ReadExactly(stream, new System.Span<byte>(buffer, offset, count)); internal static void ReadExactly(this System.IO.Stream stream, System.Span<byte> buffer) { int offset=0; while(offset<buffer.Length) { int n=stream.Read(buffer.Slice(offset)); if(n==0)throw new System.IO.EndOfStreamException(); offset+=n; } } } }